import pandas as pd
# Check whether integer codes are stored without decimals in CSV but pandas converts some columns
# Count how many raw diag values contain a dot vs not, per column
for path in ["data/encounters.csv", "data/serving_batch.csv"]:
    print("====", path)
    with open(path) as f:
        header = f.readline().strip().split(",")
        ix = [header.index(c) for c in ["diag_1","diag_2","diag_3"]]
        stats = {i: {"dot":0,"nodot":0,"q":0,"empty":0,"other":0,"n":0} for i in ix}
        examples = {i: [] for i in ix}
        for line in f:
            parts = line.rstrip("\n").split(",")
            for i in ix:
                v = parts[i]
                stats[i]["n"] += 1
                if v == "?" or v == "":
                    stats[i]["q"] += 1
                elif "." in v:
                    stats[i]["dot"] += 1
                    if len(examples[i]) < 3:
                        examples[i].append(v)
                elif v.isdigit() or (v[:1] in "VE" and v[1:].replace(".","").isdigit()):
                    stats[i]["nodot"] += 1
                else:
                    stats[i]["other"] += 1
                    if len(examples[i]) < 6:
                        examples[i].append(("OTHER", v))
        for i, name in zip(ix, ["diag_1","diag_2","diag_3"]):
            print(name, stats[i], "ex", examples[i][:6])
