# Find codes that json.loads considers extra data, including after float stringify
import json, pandas as pd
from src import codes
sb = pd.read_csv("data/serving_batch.csv", low_memory=False)
print(sb.dtypes[["diag_1","diag_2","diag_3"]])
# force numeric conversion attempts
for col in ["diag_1","diag_2","diag_3"]:
    num = pd.to_numeric(sb[col], errors="coerce")
    print(col, "numeric frac", num.notna().mean(), "int-like", ((num.dropna()%1)==0).mean())

# codes in index that aren't plain json numbers or simple strings
idx = pd.read_csv("data/patient_conditions.csv", dtype=str)
print("index code samples with non-digit", idx.loc[~idx.code.str.fullmatch(r"\d+"), "code"].value_counts().head(20))
print("index codes with dot", idx.code.str.contains(r"\.").sum())
print("index V", idx.code.str.startswith("V").sum(), "E", idx.code.str.startswith("E").sum())

# What if service json.loads each code in the register output and V15 is fine (error) but some code is "08"?
# Search all data files for codes that cause Extra data
cands = set(idx.code.unique())
cg = pd.read_csv("data/code_groups.csv", dtype=str)
cands |= set(cg.charted_code) | set(cg.register_code)
enc = pd.read_csv("data/encounters.csv", dtype=str, usecols=["diag_1","diag_2","diag_3"])
for c in enc.columns:
    cands |= set(codes.normalise(enc[c], "?").dropna().unique())
sb = pd.read_csv("data/serving_batch.csv", dtype=str, usecols=["diag_1","diag_2","diag_3"])
for c in sb.columns:
    cands |= set(codes.normalise(sb[c], "?").dropna().unique())
print("cands", len(cands))
for v in sorted(cands, key=str):
    try:
        json.loads(str(v))
    except json.JSONDecodeError as e:
        if "Extra data" in str(e):
            print("EXTRA", repr(v), e)
print("done scan")
# also float-stringified versions
for v in list(cands):
    if str(v).isdigit():
        fv = str(float(v))  # '8.0'
        try:
            json.loads(fv)
        except json.JSONDecodeError as e:
            if "Extra data" in str(e):
                print("FLOAT EXTRA", repr(v), repr(fv), e)
                break
print("no float extra? checking 8.0", end=" ")
try:
    print(json.loads("8.0"))
except Exception as e:
    print(type(e), e)
try:
    print("08", json.loads("08"))
except Exception as e:
    print("08", e)
try:
    print("250.01", json.loads("250.01"))
except Exception as e:
    print("250.01", e)
